const verifySrc=`log => {
  const cols="ABCDEFGHJ", board={};
  for(const c of cols) for(let y=1;y<=9;y++) board[c+y]=".";
  const moves=[],checks=[];let blackPasses=0,whitePasses=0;
  for(const entry of log){
    const s=entry.response.content.filter(x=>x.type==="text").map(x=>x.text).join("\\n");
    if(entry.action==="play"){
      const match=s.match(/Your opponent played ([A-HJ][1-9])\\./);
      const reply=match?match[1]:s.includes("Your opponent passed.")?"pass":null;
      if(!reply)throw Error("Missing actual reply");
      for(const [color,point] of [["X",entry.move],["O",reply]]){
        moves.push({number:moves.length+1,color:color==="X"?"B":"W",move:point});
        if(point==="pass"){if(color==="X")blackPasses++;else whitePasses++;}
        else {if(board[point]!==".")throw Error("Actual placement not empty "+point);board[point]=color;}
      }
    }
    const observed=inspect(entry.response).board;
    const mismatches=Object.keys(board).filter(p=>board[p]!==observed[p]);
    const captures=s.match(/Captured by Black: (\\d+); by White: (\\d+)/);
    const ko=s.match(/Ko point: ([^.]+)\\./);
    const valid=mismatches.length===0&&captures&&+captures[1]===0&&+captures[2]===0&&ko&&ko[1]==="none";
    checks.push({afterMove:moves.length,action:entry.action,fullBoardMatches:mismatches.length===0,capturesBlack:captures?+captures[1]:null,capturesWhite:captures?+captures[2]:null,ko:ko?ko[1]:null,valid:!!valid});
    if(!valid)throw Error("Historical mismatch "+JSON.stringify(checks.at(-1)));
  }
  return {actualMoves:moves,checks,allChecksMatch:checks.every(x=>x.valid),moves:moves.length,boards:checks.length,blackPasses,whitePasses,blackStones:Object.values(board).filter(v=>v==="X").length,whiteStones:Object.values(board).filter(v=>v==="O").length};
}`;
